import{_ as a,o as e,c as t,ag as n}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第118章 叶老师","description":"","frontmatter":{},"headers":[],"relativePath":"第118章_叶老师.md","filePath":"第118章_叶老师.md"}'),o={name:"第118章_叶老师.md"};function _(r,p,s,d,l,i){return e(),t("div",null,[...p[0]||(p[0]=[n('<h1 id="第118章-叶老师" tabindex="-1">第118章 叶老师 <a class="header-anchor" href="#第118章-叶老师" aria-label="Permalink to &quot;第118章 叶老师&quot;">​</a></h1><p>后街拆完的第二天早上，我才听清奶奶那条三秒的语音。</p><p>风太大，前一晚我把手机贴着耳朵，只听见呼呼的响，还有半句含糊的话。回了宿舍，夜静下来，我又点开听了一遍，奶奶说，聿崽，去看看叶老师吧。</p><p>她声音很轻，带着刚睡醒的哑，背景里有水烧开的声音，咕嘟咕嘟的。我愣了很久，给她回过去，她没接，再打过去，她说在熬粥，让我中午回去喝。我问怎么突然想起叶老师，她说，梦见你高中那会儿了，你叶老师在黑板上写句子，你坐在底下抄，抄得很认真。</p><p>我说是，好久没去了，是该去看看。</p><p>叶老师教我们英语，高一到高三，整三年。她个子不高，头发总盘得很低，说话慢，走路也慢，粉笔字写得极清楚。她有一句口头禅，逢新班必说，单词要放进句子里，人要放进日子里。</p><p>当年我们都不懂，只觉得顺口，拿来编成顺口溜下课喊。她也不恼，站在讲台上笑，等我们喊完，才说，笑完了就记住了，记住也好。</p><p>高中那会儿我和江苒都在她班上，我坐第三排靠窗，江苒坐我后一排靠门。早读我背单词总卡壳，abandon背了三天还是拼不全，江苒就在后面用笔尖戳我后背，小声接下半个。她英语比我好，语感好，叶老师总夸她，说这孩子是把自己放进句子里了。</p><p>毕业后我就没再见过叶老师。只听说她没带毕业班了，退到高一教基础，喉咙不好，做了个小手术，说话比以前更慢了。奶奶和她见过一次，在菜场，奶奶买丝瓜，她买豆腐，两个人聊了几句，奶奶回来跟我说，叶老师还问起你，问你那本小说写完了没。</p><p>中午我回去喝粥，奶奶已经能自己下地了，走得很慢，扶着墙，一步一挪。粥熬得很稠，放了红薯，甜香漫了一屋子。她给我盛了一大碗，又往我碗里埋了个鸡蛋，说吃完去，空手别去，带点她晒的萝卜干，叶老师喉咙不好，吃粥就这个好。</p><p>我把碗洗了，装了一小罐萝卜干，又把那本打印出来的小说草稿装进包里。草稿很厚，用夹子夹着，边角卷了起来。奶奶看我装，问，是拿去给叶老师看吗。我说嗯，她教句子，总得让她看看我写的句子。奶奶笑，皱纹挤在一起，说对，作文都是她改的，你那点底子都是她打的。</p><p>午后，太阳很毒，我坐公交回高中。市三中在老街另一头，下车还要走一段坡。校门口换了新的伸缩门，保安室贴着访客登记，我写了名字和事由，保安看了一眼，放我进去，说教师办公楼还在老地方，没搬。</p><p>一进校门，桂花香就扑过来。操场翻新了，塑胶跑道红得发亮，几个高一的孩子在树下背书，声音参差不齐。我沿着那条坡道往上走，两边是梧桐，叶子被晒得卷边，踩上去沙沙响。教学楼刷了新漆，只有那栋办公楼没动，白墙灰瓦，楼梯还是水泥的，扶手磨得发亮。</p><p>叶老师在二楼最里面那间，小办公室，门口挂着高一英语组的牌子。我站在门口没敢立刻敲，听见里面有说话声，很慢，是她的声音，在讲一个句子。她说，你看这个词，alone，一个人，很孤单对不对，你把它放进句子里，I am not alone，就不孤单了。单词是死的，句子是活的。</p><p>我鼻子一酸，轻轻敲了敲门。</p><p>门开，叶老师站在里面，比记忆里矮了一点，头发白了大半，还是低低盘着，手里捏着半截粉笔。她眯着眼看我，看了两秒，忽然笑了，说，聿崽吧，长这么高了，快进来，外面晒。</p><p>办公室很小，两张桌子拼在一起，上面堆满了作业本，还有一杯胖大海，水汽还没散。她让我坐，给我倒水，一次性纸杯烫手，我换着手捧着，跟昨晚捧糖水纸碗一个姿势。她问，奶奶身子可好些了，我说能下地了，能熬粥了。她点头，说那就好，老人摔一跤，伤的是心气，得慢慢养。</p><p>她问起近况，我说了实验，说了那本小说，说写了三年，还没写完，暂缓了。她没催，只问，写到哪了。我说写到后街拆了，写到一碗糖水换了纸碗。她笑，说好，日子在变，句子也得变。</p><p>我说起江苒，说她在南州读语言，背单词背到嘴皮起泡。叶老师眼睛亮了一下，说那孩子有语感，当年我就说，她以后吃语言这碗饭。她顿了顿，又问，你们呢。我低头转着纸杯，说分开了，平安结退回来了，放在抽屉里。办公室里安静了一会儿，风扇呼呼转，吹得作业本哗哗响。</p><p>叶老师没劝，也没叹气，只从抽屉里拿出一本小册子，牛皮纸封面，边角磨毛了。她翻开给我看，里面全是句子，一行英文，一行中文，字迹是她的，很清楚。她说，这是我这些年攒的，学生写的好的句子，还有我自己写的。她指着其中一句给我念，We put words into sentences, and put ourselves into days. 单词放进句子，人放进日子。</p><p>她说，你当年背abandon总背不下来，我就让你造句，你造的是，I will not abandon my grandma. 我不会丢下我奶奶。全班都笑了，我没笑，我说这个句子好，有人味。从那以后你背单词就顺了，因为你把人放进去了。</p><p>我想起来了，是有这么回事。那天江苒在后面笑得最大声，下课还学我，I will not abandon my grandma，学得抑扬顿挫。我追着她打，从三楼追到一楼，梧桐叶子落了一身。</p><p>叶老师把小册子往我这边推了推，说送你了，你写小说用得上。你这孩子，重感情，写东西容易陷在词里，陷在一个人身上。出不来，句子就死了。把单词放进句子，把人放进日子，日子往前走，句子才能活。</p><p>我把册子收下，很薄，拿在手里却沉。我把包里的草稿拿出来，双手递过去，说老师，您帮我看看句子。她戴上老花镜，翻得很慢，看到有错字，就用铅笔轻轻圈出来，不说话。看到后街那段，她停了很久，说，这碗糖水写得好，有热气。她又翻到奶奶那段，说，奶奶写得也好，让人想起自己的妈。</p><p>看到最后，她合上本子，说写得不急，暂缓也对。小说跟粥一样，得小火熬，大火就糊了。你奶奶病着，你照顾她，这就是把人放进日子，日子不会亏待你。</p><p>临走时她送我到楼梯口，从口袋里摸出两颗话梅，塞进我手里，说润喉的，你熬夜改稿含一颗。我说老师你喉咙不好，你留着。她摆手，说我还有一抽屉呢，学生送的。</p><p>下楼时上课铃响了，高一的孩子往教室跑，书包甩得老高。梧桐叶子落下来，落在我肩上，我没拍，带着它往校门口走。手机震了一下，是周野发来的，说李婆在前街口摆上小车了，第一晚，让我们去捧场，站着喝也去。我回了个好，又问，顾远去吗。他说去，还说温棠也要去，带着那本草稿的问题。</p><p>走到校门口，我回头看了一眼，办公楼二楼的窗开着，叶老师站在窗边，正往下看，见我回头，朝我挥了挥手里的粉笔。我也挥手，萝卜干罐子在包里晃，哐当一声，小册子贴着胸口，隔着衣服都能感觉到它的边角。</p><p>公交车上人不多，我翻开小册子，第一页是叶老师新写的，墨还没干透。她写，聿崽，粥要趁热喝，路要慢慢走，句子要一个一个写。</p><p>我把话梅含进嘴里，酸味漫开，喉咙一紧，眼睛有点潮。窗外老街往后退，奶奶家的屋顶一闪而过，烟囱里正冒着烟，想来是粥又烧开了。</p>',30)])])}const u=a(o,[["render",_]]);export{m as __pageData,u as default};
